// Pure, dependency-free proration maths shared by the server actions (resize,
// disk expansion, downgrade) and the client pickers that DISPLAY the number.
// No server-only imports, exactly like lib/wallet-split.ts — so the figure the
// customer sees is byte-for-byte the figure that gets charged or credited.

import { vpsEffectiveMonthly } from "./billing-terms";
import { currentPromo, promoPriceCents, type Promo } from "./promotions";

/** Average calendar month in ms (365.25/12 ≈ 30.44d). */
export const MS_PER_AVG_MONTH = 30.44 * 86400_000;

/**
 * Months left on a term, clamped to something sane.
 *
 * The clamp matters on the CREDIT side: `renewNow` can stack `expiresAt` many
 * terms into the future, and an unclamped credit multiplies the monthly delta by
 * every stacked month. The client estimate already clamped to one term while the
 * server did not, so the two disagreed and the server was the generous one.
 */
export function remainingMonths(expiresAt: Date | null, now: number, capMonths?: number): number {
  if (!expiresAt) return 0;
  const raw = Math.max(0, (expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
  return capMonths && capMonths > 0 ? Math.min(raw, capMonths) : raw;
}

/**
 * The prorated difference between two monthly plan prices over the remaining
 * term, priced the way a FRESH order for the same product would be priced today.
 *
 * Why this exists (2026-07-25): proration used the raw list monthly delta while
 * the original purchase applied BOTH the term discount (lib/order.ts) and the
 * seasonal promo. Upgrading therefore cost far more than buying the target plan
 * outright for the same end date — on a 36-month term with a 30% promo running,
 * $1,044.45 to upgrade versus $665.08 fresh: the customer overpaid $379.37. The
 * mirror image was worse in kind though not yet reachable: the downgrade CREDIT
 * used the same undiscounted delta, so it refunded more than was ever paid — a
 * self-service money printer the moment the plan catalogue allows a downgrade.
 *
 * Both directions now price off the SAME function, so they cannot drift apart:
 *   effective monthly (term discount applied) → promo applied → × months left.
 *
 * `promo` is injected so a caller can price against a specific promo; it defaults
 * to whatever is running now, which is what a fresh order today would pay.
 */
export function prorateDeltaCents(opts: {
  fromMonthlyCents: number;
  toMonthlyCents: number;
  termMonths: number;
  monthsRemaining: number;
  promo?: Promo;
  now?: Date;
}): number {
  const promo = opts.promo ?? currentPromo(opts.now ?? new Date());
  const eff = (monthly: number) =>
    promoPriceCents(vpsEffectiveMonthly(monthly, opts.termMonths), promo);
  const delta = eff(opts.toMonthlyCents) - eff(opts.fromMonthlyCents);
  return Math.round(delta * Math.max(0, opts.monthsRemaining));
}

/** Upgrade charge — never negative. */
export function prorateUpgradeCents(opts: Parameters<typeof prorateDeltaCents>[0]): number {
  return Math.max(0, prorateDeltaCents(opts));
}

/** Downgrade credit — never negative; caller passes from=old, to=new. */
export function prorateDowngradeCreditCents(
  opts: Parameters<typeof prorateDeltaCents>[0]
): number {
  return Math.max(0, -prorateDeltaCents(opts));
}

import type { Prisma } from "@prisma/client";

export class InsufficientBalanceError extends Error {
  constructor() {
    super("INSUFFICIENT_BALANCE");
    this.name = "InsufficientBalanceError";
  }
}

/**
 * Atomically debit a wallet inside a transaction. The conditional updateMany
 * (balanceCents >= cents) prevents the read-check-then-decrement race that could
 * otherwise drive balances negative under concurrent spend. Throws
 * InsufficientBalanceError (rolling back the tx) if funds are insufficient.
 */
export async function debitWallet(
  tx: Prisma.TransactionClient,
  userId: string,
  cents: number
): Promise<void> {
  if (cents <= 0) return;
  const res = await tx.user.updateMany({
    where: { id: userId, balanceCents: { gte: cents } },
    data: { balanceCents: { decrement: cents } },
  });
  if (res.count === 0) throw new InsufficientBalanceError();
}
// Pure, dependency-free wallet/card split math shared by the client wizards
// (DeployWizard, ResizePicker) and the server actions (payAndDeploy,
// resizeServer). Keeping it here — with NO server-only imports — guarantees the
// split the customer SEES is byte-for-byte the split that gets CHARGED.

/**
 * Stripe rejects card charges under ~$0.50. We never send a card amount below
 * this; when the natural remainder would fall under it we leave exactly this
 * much on the card and apply slightly less wallet credit (see walletSplit).
 */
export const STRIPE_MIN_CENTS = 50;

export type WalletSplit = {
  /** Cents taken from the customer's existing wallet balance. */
  walletApplied: number;
  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
  cardCents: number;
  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
  clampedForStripeMin: boolean;
};

/**
 * Split a due amount between the wallet and the card, honoring the customer's
 * "apply my balance" toggle and Stripe's minimum-charge floor.
 *
 * - `useWallet` off  → everything on the card.
 * - wallet covers all → cardCents = 0 (caller pays entirely from wallet, no Stripe).
 * - partial cover     → walletApplied = min(balance, due), card = the remainder.
 * - tiny remainder    → if 0 < card < STRIPE_MIN_CENTS and the wallet can't cover
 *   the whole thing, reduce walletApplied so exactly STRIPE_MIN_CENTS lands on the
 *   card (never send Stripe a sub-minimum charge). Integer-cent exact throughout.
 */
export function walletSplit(opts: {
  dueCents: number;
  balanceCents: number;
  useWallet: boolean;
}): WalletSplit {
  const dueCents = Math.max(0, Math.round(opts.dueCents));
  const balanceCents = Math.max(0, Math.round(opts.balanceCents));
  if (dueCents <= 0) return { walletApplied: 0, cardCents: 0, clampedForStripeMin: false };

  let walletApplied = opts.useWallet ? Math.min(balanceCents, dueCents) : 0;
  let cardCents = dueCents - walletApplied;
  let clampedForStripeMin = false;

  // A tiny non-zero card remainder that Stripe would reject. This only happens
  // when the wallet can't cover the whole charge (otherwise cardCents === 0), so
  // the least-surprising fix is to leave STRIPE_MIN_CENTS on the card and apply a
  // touch less wallet. Guarded so walletApplied can never go negative.
  if (cardCents > 0 && cardCents < STRIPE_MIN_CENTS && dueCents >= STRIPE_MIN_CENTS) {
    walletApplied = dueCents - STRIPE_MIN_CENTS;
    cardCents = STRIPE_MIN_CENTS;
    clampedForStripeMin = true;
  }
  return { walletApplied, cardCents, clampedForStripeMin };
}
/**
 * Billing term definitions + discount math, shared by ordering, renewal,
 * the deploy wizard, invoices and the domain flow. Discounts are the platform's
 * promo (longer commitment = cheaper); tune here (or later via admin Settings).
 */

export type VpsTerm = { months: number; label: string; short: string; discountPct: number };

export const VPS_TERMS: VpsTerm[] = [
  { months: 1, label: "Monthly", short: "1 mo", discountPct: 0 },
  { months: 12, label: "Annual", short: "1 yr", discountPct: 10 },
  { months: 24, label: "Biennial", short: "2 yr", discountPct: 15 },
  { months: 36, label: "Triennial", short: "3 yr", discountPct: 20 },
];

export function vpsTerm(months: number): VpsTerm {
  return VPS_TERMS.find((t) => t.months === months) ?? VPS_TERMS[0];
}

/** Total charge (cents) for a plan over a term, discount applied. */
export function vpsTermPriceCents(monthlyCents: number, months: number): number {
  const t = vpsTerm(months);
  return Math.round(monthlyCents * months * (1 - t.discountPct / 100));
}

/** Effective monthly-equivalent price after the term discount (for "$/mo" display). */
export function vpsEffectiveMonthly(monthlyCents: number, months: number): number {
  return Math.round(vpsTermPriceCents(monthlyCents, months) / months);
}

export type DomainTerm = { years: number; label: string; discountPct: number };

export const DOMAIN_TERMS: DomainTerm[] = [
  { years: 1, label: "1 year", discountPct: 0 },
  { years: 2, label: "2 years", discountPct: 5 },
  { years: 3, label: "3 years", discountPct: 10 },
];

export function domainTerm(years: number): DomainTerm {
  return DOMAIN_TERMS.find((t) => t.years === years) ?? DOMAIN_TERMS[0];
}

/** Total charge (cents) for a domain over N years, discount applied. */
export function domainTermPriceCents(perYearCents: number, years: number): number {
  const t = domainTerm(years);
  return Math.round(perYearCents * years * (1 - t.discountPct / 100));
}

/** Add whole months to a date (UTC-safe enough for billing windows). */
export function addMonths(from: Date, months: number): Date {
  const d = new Date(from);
  d.setMonth(d.getMonth() + months);
  return d;
}

