434:/* ------------------------------------------------------------------ *
435: * Renewal commit (wallet) + card auto-charge
436: * ------------------------------------------------------------------ */
437:
438:/**
439: * Advance the term and take the money from the wallet, atomically.
440: *
441: * This is the ONLY place a VPS renewal is granted, whether the wallet was funded
442: * by a top-up, a referral credit or the saved card moments ago. One money path
443: * means a partial failure can never half-apply a renewal: either the period
444: * advances AND the wallet is debited AND the invoice exists, or none of it happened.
445: *
446: * The compare-and-swap on `expiresAt` is the idempotency guard. A retried sweep, a
447: * second worker or a concurrent `renewNow` all read the same snapshot expiry; only
448: * the first `updateMany` to match it writes, and every loser rolls back its debit
449: * and its invoice with the transaction. Zero rows matched = someone else already
450: * renewed this period, which is a success for us, not an error.
451: */
452:async function commitRenewal(opts: {
453:  server: DueServer;
454:  charge: RenewalCharge;
455:  newExpiry: Date;
456:}): Promise<"renewed" | "insufficient" | "already"> {
457:  const { server, charge, newExpiry } = opts;
458:  const renewCents = charge.totalCents;
459:  const { extraDiskCents, extraDiskMonthlyCents } = charge;
460:  const periodStart = server.expiresAt!;

460:  const periodStart = server.expiresAt!;
461:
462:  try {
463:    await db.$transaction(async (tx) => {
464:      const advanced = await tx.server.updateMany({
465:        where: { id: server.id, expiresAt: server.expiresAt },
466:        data: {
467:          expiresAt: newExpiry,
468:          // The period is paid, so the collection state that belonged to it dies
469:          // with it. Leaving a stage behind would hand the NEXT period a
470:          // half-spent retry budget and the wrong dunning email.
471:          dunningStage: 0,
472:          dunningNextAt: null,
473:          dunningPayUrl: null,
474:        },
475:      });
476:      if (advanced.count === 0) throw new AlreadyRenewedError();
477:      await debitWallet(tx, server.userId, renewCents);
478:      await tx.walletTransaction.create({
479:        data: {
480:          userId: server.userId,
481:          amountCents: -renewCents,
482:          description: `Renewal: ${charge.label} (${server.hostname})`,
483:        },
484:      });
485:      // PAID invoice for this renewal period. Inside the CAS-guarded tx, so a
486:      // retried/concurrent sweep hits AlreadyRenewedError and rolls back —
487:      // never producing a second invoice for the same period.
488:      await tx.invoice.create({
489:        data: invoiceCreateData({
490:          userId: server.userId,
491:          description: `Renewal: ${charge.label} (${server.hostname})`,
492:          status: "PAID",
493:          period: { start: periodStart, end: newExpiry },
494:          // Extra disk gets its OWN line so the customer sees exactly what the
495:          // permanent storage costs each cycle; the lines sum back to renewCents.
496:          lineItems: [
497:            {
498:              description: `${charge.label} — ${server.hostname}`,
499:              qty: 1,
500:              unitCents: renewCents - extraDiskCents,
501:              amountCents: renewCents - extraDiskCents,
502:            },
503:            ...(extraDiskCents > 0
504:              ? [
505:                  {
506:                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthlyCents / 100).toFixed(2)}/mo)`,
507:                    qty: 1,
508:                    unitCents: extraDiskCents,
509:                    amountCents: extraDiskCents,
510:                  },
511:                ]
512:              : []),
513:          ],
514:        }),
515:      });
516:      await tx.auditLog.create({
517:        data: { userId: server.userId, action: "billing.renewed", detail: server.id },
518:      });
519:    });
520:  } catch (e) {
521:    if (e instanceof InsufficientBalanceError) {
522:      console.log(`[billing] insufficient balance for ${server.hostname} — falling through to grace/suspend`);
523:      return "insufficient";
524:    }
525:    if (e instanceof AlreadyRenewedError) return "already"; // someone else advanced the period
526:    throw e;
527:  }
528:
529:  // The period is settled. Any 3-D Secure challenge still hanging off it is a
530:  // loaded gun: anything that later confirms that intent takes a SECOND payment
531:  // for a period we have already been paid for. Only worth a Stripe round-trip
532:  // when this server was actually mid-dunning.
533:  if (server.dunningStage > 0 || server.dunningPayUrl) {
534:    await cancelPendingChargeForMarker(
535:      server.user.stripeCustomerId,
536:      renewalChargeMarker(server.id, periodStart),
537:    );
538:  }
539:  return "renewed";
540:}
