542:/**
543: * Charge the saved card for the wallet shortfall, then renew.
544: *
545: * The card NEVER pays the invoice directly. It credits the wallet with exactly
546: * what Stripe captured, and `commitRenewal` then debits the FULL renewal from the
547: * wallet — identical to how checkout splits a purchase. That ordering is what
548: * makes a crash safe in both directions: money captured but not yet applied sits
549: * in the customer's wallet as credit (visible, spendable, refundable), and a
550: * renewal can never be granted without a matching debit.
551: *
552: * TWO idempotency guards ride on every attempt:
553: *  - `marker` (server + period) — a permanent pre-flight lookup at Stripe for a
554: *    live PaymentIntent for this exact period, so a crash between "Stripe captured"
555: *    and "we recorded it" replays instead of charging again.
556: *  - `idempotencyKey` (server + period + attempt + amount) — Stripe replays an
557: *    identical request for 24h, which covers two overlapping sweeps of the SAME
558: *    scheduled attempt. The attempt and amount are in the key because a genuine
559: *    day-3 retry, or a retry for a different remainder after the wallet moved, is a
560: *    deliberately NEW charge; reusing the key there would make Stripe reject it.
561: *
562: * And the credit itself is guarded by the UNIQUE index on
563: * `WalletTransaction.stripePaymentIntentId`, so even a replayed capture credits once.
564: *
565: * @returns true when the term was actually extended.
566: */
567:async function attemptCardRenewal(opts: {
568:  server: DueServer;
569:  charge: RenewalCharge;
570:  cardCents: number;
571:  newExpiry: Date;
572:  now: Date;
573:  cfg: DunningConfig;
574:}): Promise<boolean> {
575:  const { server, charge, cardCents, newExpiry, now, cfg } = opts;
576:  const user = server.user;
577:  const periodStart = server.expiresAt!;
578:  const marker = renewalChargeMarker(server.id, periodStart);
579:  const idempotencyKey = `nxeon_renew_${server.id}_${periodStart.getTime()}_a${server.dunningStage}_${cardCents}`;
580:  const cardLabel = savedCardLabel(user) ?? "your saved card";
581:
582:  const result = await chargeSavedCardOffSession({
583:    user,
584:    amountCents: cardCents,
585:    description: `Renewal: ${charge.label} (${server.hostname})`,
586:    marker,
587:    idempotencyKey,
588:    metadata: {
589:      nxeonServerId: server.id,
590:      nxeonPeriodStart: periodStart.toISOString(),
591:      nxeonKind: "renewal",
592:    },
593:  });
594:
595:  if (result.ok) {
596:    // Exactly what Stripe took, not what we asked for — a replayed intent can carry
597:    // an older amount and the ledger must match the bank, not our intent.
598:    const credited = await creditOffSessionCharge({
599:      userId: server.userId,
600:      amountCents: result.amountCents,
601:      description: `Card payment for ${server.hostname} renewal (${cardLabel})`,
602:      paymentIntentId: result.paymentIntentId,
603:      // No invoice for the card leg: `commitRenewal` issues ONE paid invoice for
604:      // the whole renewal, and a second document for the card portion would
605:      // double-count the same revenue.
606:    });
607:    const outcome = await commitRenewal({ server, charge, newExpiry });
608:
609:    // The receipt is tied to the CREDIT, not the renewal: `creditOffSessionCharge`
610:    // returns false on the P2002 that means "already credited", so a replayed
611:    // capture cannot email the same customer a second receipt for one charge.
612:    if (credited) {
613:      await mail(
614:        user.email,
615:        user.id,
616:        emails.paymentReceipt(
617:          fmtUsd(result.amountCents),
618:          `${charge.label} — ${server.hostname}`,
619:          user.cardLast4 ?? "",
620:        ),
621:      );
622:    }
623:
624:    if (outcome === "insufficient") {
625:      // The card paid, the wallet was credited, and the debit STILL failed — the
626:      // customer spent the credit between our split read and the transaction. The
627:      // money is not lost, it is sitting in their wallet; re-run shortly rather
628:      // than charging again (the marker replays this same capture, so the next
629:      // pass cannot take a second payment) and do NOT count it as a dunning
630:      // failure, because nothing about their card went wrong.
631:      console.error(
632:        `[billing] ${server.hostname}: card captured ${fmtUsd(result.amountCents)} but the wallet debit fell short — retrying shortly`,
633:      );
634:      await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
635:      return false;
636:    }
637:    if (outcome === "renewed") {
638:      console.log(
639:        `[billing] renewed ${server.hostname} until ${newExpiry.toISOString()} (card ${fmtUsd(result.amountCents)}${result.replayed ? ", replayed" : ""})`,
640:      );
641:    }
642:    return true;
643:  }
644:
645:  if (result.kind === "transient") {
646:    // Our side or Stripe's side wobbled. Never a dunning event: a misclassified
647:    // transient costs a delayed renewal, a misclassified decline costs a paid-up
648:    // customer their server. The attempt counter is untouched.
649:    console.warn(`[billing] transient charge error for ${server.hostname}: ${result.message}`);
650:    await rescheduleAttempt(server, new Date(now.getTime() + TRANSIENT_RETRY_MS));
651:    return false;
652:  }
653:
654:  if (result.kind === "unavailable") {
655:    // `hasChargeableCard` already proved Stripe is configured and both ids are
656:    // present, and `walletSplit` keeps the amount above Stripe's floor — so the
657:    // only way here is `resource_missing`: the payment method no longer exists at
658:    // Stripe. Not a decline; there is nothing to retry until a new card is saved.
659:    // Clearing the columns matters twice over: the portal stops claiming a card is
660:    // on file, and `suspendDueAt` stops granting card-customer runway to an account
661:    // that has no card at all.
662:    console.warn(`[billing] saved card unusable for ${server.hostname}: ${result.message}`);
663:    await forgetMissingPaymentMethod(server.userId).catch((e) =>
664:      console.error("[billing] could not clear missing payment method", e),
665:    );
666:    // `server.user` is deliberately NOT mutated: this pass keeps the card-customer
667:    // runway and only the NEXT pass falls back to the shorter no-card grace. More
668:    // runway is always the safe direction for a fault the customer never saw coming.
669:    await rescheduleAttempt(server, null);
670:    await notify(
671:      server.userId,
672:      "Your saved card is no longer available",
673:      `We couldn't use the card saved for ${server.hostname} — your bank or Stripe no longer recognises it. Add a card to keep your services renewing automatically.`,
674:      "/dashboard/billing",
675:    );
676:    return false;
677:  }
678:
679:  if (result.kind === "requires_action") {
680:    // 3-D Secure. Off-session there is no browser to satisfy the challenge, so the
681:    // answer is a hosted Checkout link: the customer completes the bank step on
682:    // Stripe's own page, the money lands as wallet credit and the next sweep
683:    // renews from the wallet. This is NOT a decline — nothing about the card is
684:    // wrong — so it must never consume a retry, or a customer who simply hasn't
685:    // opened their email yet would be dunned toward suspension for their bank's
686:    // security policy.
687:    let payUrl = server.dunningPayUrl;
688:    if (!payUrl) {
689:      payUrl = await createOutstandingCheckout({
690:        user,
691:        amountCents: cardCents,
692:        hostname: server.hostname,
693:        serverId: server.id,
694:      });
695:      if (payUrl) {
696:        await db.server.update({ where: { id: server.id }, data: { dunningPayUrl: payUrl } });
697:        await mail(
698:          user.email,
699:          user.id,
700:          emails.paymentActionRequired(server.hostname, fmtUsd(cardCents), payUrl),
701:        );
702:        await notify(
703:          server.userId,
704:          `${server.hostname} — your bank needs to confirm the payment`,
705:          `Your card issuer asked for an extra verification step for ${fmtUsd(cardCents)}. Confirming it finishes the renewal. Nothing is suspended.`,
706:          `/dashboard/servers/${server.id}`,
707:        );
708:      }
709:    }
710:    // Re-check daily rather than hourly: the challenge does not move, and the same
711:    // link is already in their inbox. `dunningPayUrl` being set is what stops the
712:    // email repeating for this period; `clearStaleDunning`/`commitRenewal` clear it.
713:    server.dunningPayUrl = payUrl;
714:    await rescheduleAttempt(server, new Date(now.getTime() + MIN_RETRY_GAP_MS));
715:    console.log(`[billing] ${server.hostname} awaiting 3-D Secure confirmation for ${fmtUsd(cardCents)}`);
716:    return false;
717:  }
718:
719:  // Hard decline — the issuer said no. This is the only outcome that spends an
720:  // attempt and moves the customer along the dunning sequence.
721:  await recordDeclinedAttempt({ server, cardCents, now, cfg, reason: result.message });
722:  return false;
723:}
