   111	        planId: resize.planId,
   112	        actorUserId: resize.userId,
   113	        chargeCents: resize.chargeCents,
   114	      });
   115	      await settle(sessionId, "DONE", resize.serverId);
   116	      return { redirect: back, fulfilled: true, kind: "resize" };
   117	    } catch (e) {
   118	      const msg = String((e as Error)?.message ?? e);
   119	      await settle(sessionId, "FAILED", msg);
   120	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
   121	    }
   122	  }
   123	
   124	  const expand = await getCheckoutDiskExpandIntent(sessionId);
   125	  if (expand) {
   126	    const back = `${base}/dashboard/servers/${expand.serverId}`;
   127	    if (!(await claim(sessionId, "diskExpand"))) {
   128	      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
   129	    }
   130	    try {
   131	      await applyDiskExpand({
   132	        serverId: expand.serverId,
   133	        addGB: expand.addGB,
   134	        actorUserId: expand.userId,
   135	        chargeCents: expand.chargeCents,
   136	      });
   137	      await settle(sessionId, "DONE", expand.serverId);
   138	      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
   139	    } catch (e) {
   140	      const msg = String((e as Error)?.message ?? e);
   141	      await settle(sessionId, "FAILED", msg);
   142	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
   143	    }
   144	  }
   145	
   146	  // Plain wallet top-up: crediting above is the whole job.
   147	  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
