95:/**
96: * What a renewal costs. Lives here (rather than being copied a third time)
97: * because BOTH the worker sweep and the customer-facing "settle the balance"
98: * link have to quote the same number — `renewNow` and the sweep already carry
99: * the comment "the two renewal paths must never disagree", and a self-service
100: * pay link that quotes a different total than the sweep charges is exactly how
101: * that goes wrong.
102: *
103: * Pure: prices are passed in so the worker can read the admin settings once per
104: * sweep instead of once per server.
105: */
106:export type RenewalCharge = {
107:  months: number;
108:  totalCents: number;
109:  /** The extra-root-disk portion, which gets its own invoice line. */
110:  extraDiskCents: number;
111:  extraDiskMonthlyCents: number;
112:  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
113:  label: string;
114:};
115:
116:export type PricedServer = {
117:  termMonths: number;
118:  extraDiskGB: number;
119:  plan: { name: string; priceCents: number };
120:  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
121:  dedicatedIp: unknown | null;
122:};
123:
124:export function renewalCharge(
125:  server: PricedServer,
126:  prices: { ipMonthlyCents: number; extraDiskPerGbCents: number },
127:): RenewalCharge {
128:  const isGame = !!server.gamePlan;
129:  const months = isGame ? server.gamePlan!.termMonths : vpsTerm(server.termMonths).months;
130:  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
131:  // are a flat all-in price and never carry the add-on lines.
132:  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
133:  const extraDiskCents = extraDiskMonthlyCents * months;
134:  const totalCents = isGame
135:    ? server.gamePlan!.priceCents
136:    : vpsTermPriceCents(server.plan.priceCents, months) +
137:      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
138:      // not off the intent flag — a NAT-fallback server must never be charged for
139:      // an IP it never received.
140:      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
141:      extraDiskCents;
142:  return {
143:    months,
144:    totalCents,
145:    extraDiskCents,
146:    extraDiskMonthlyCents,
147:    label: isGame ? server.gamePlan!.name : `${server.plan.name} VPS`,
148:  };
149:}
