171:/**
172: * Get-or-create the Stripe customer for an account and remember its id.
173: *
174: * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
175: * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
176: * person and strand the card on whichever one lost. The idempotency key — derived
177: * only from our own user id — is what stops that: Stripe replays the first
178: * customer instead of creating a second.
179: */
180:export async function ensureStripeCustomer(user: CardUser): Promise<string> {
181:  if (user.stripeCustomerId) return user.stripeCustomerId;
182:  const fresh = await db.user.findUnique({
183:    where: { id: user.id },
184:    select: { stripeCustomerId: true },
185:  });
186:  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;
187:
188:  const customer = await stripe().customers.create(
189:    {
190:      email: user.email,
191:      name: user.name || undefined,
192:      metadata: { nxeonUserId: user.id },
193:    },
194:    { idempotencyKey: `nxeon_customer_${user.id}` },
195:  );
196:  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
197:  return customer.id;
198:}
