200:/**
201: * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
202: *
203: * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
204: * integration anywhere in this codebase and no publishable key plumbed to the
205: * browser; a redirect to Stripe's own page reuses the exact flow that already
206: * takes money for deploys, upgrades and top-ups.
207: *
208: * `usage: "off_session"` is load-bearing: it records a mandate that covers the
209: * unattended renewal charges we make later. Without it many issuers (and every
210: * SCA-regulated card) reject the first off-session charge outright, which would
211: * turn "saved card" into "card that is declined once a month".
212: */
213:export async function createCardSetupSession(
214:  user: CardUser,
215:  returnPath = "/dashboard/billing",
216:): Promise<string | null> {
217:  if (!stripeConfigured()) return null;
218:  const customerId = await ensureStripeCustomer(user);
219:  const base = appBase();
220:  const session = await stripe().checkout.sessions.create({
221:    mode: "setup",
222:    customer: customerId,
223:    payment_method_types: ["card"],
224:    setup_intent_data: { metadata: { nxeonUserId: user.id } },
225:    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
226:    // Deliberately NOT /api/stripe/confirm. A setup session has no amount and
227:    // `payment_status: "unpaid"`, so the shared fulfil path would classify it as a
228:    // wallet top-up and flash "Payment received — your balance updates within
229:    // seconds" at someone who only saved a card. We finalise through our own
230:    // server action instead.
231:    success_url: `${base}${returnPath}?card_setup={CHECKOUT_SESSION_ID}`,
232:    cancel_url: `${base}${returnPath}?card_setup=canceled`,
233:  });
234:  return session.url;
235:}
