462:/**
463: * Stable per-purpose marker written into PaymentIntent metadata.
464: *
465: * This is a SECOND idempotency guard that does not expire. Stripe's own
466: * idempotency keys are only honoured for 24 hours, and our dunning schedule spans
467: * six days, so the key alone cannot answer "have we already been paid for this
468: * period?". Before charging we look for a live PaymentIntent carrying this marker
469: * and reuse it — so a crash between "Stripe captured the money" and "we recorded
470: * the payment intent id" can never turn into a second charge.
471: */
472:export function renewalChargeMarker(serverId: string, periodStart: Date): string {
473:  return `renew:${serverId}:${periodStart.toISOString()}`;
474:}
475:
476:/** Marker for an automatic wallet top-up: at most one per account per day. */
477:export function autoRechargeMarker(userId: string, now: Date): string {
478:  return `autorecharge:${userId}:${now.toISOString().slice(0, 10)}`;
479:}
