508:export async function chargeSavedCardOffSession(opts: {
509:  user: CardUser;
510:  amountCents: number;
511:  description: string;
512:  marker: string;
513:  idempotencyKey: string;
514:  metadata?: Record<string, string>;
515:}): Promise<OffSessionResult> {
516:  const { user, amountCents, description, marker, idempotencyKey } = opts;
517:  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
518:  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
519:    return { ok: false, kind: "unavailable", message: "No saved card" };
520:  }
521:  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
522:  // the belt-and-braces check so a future caller can't send a rejectable amount.
523:  if (amountCents < STRIPE_MIN_CENTS) {
524:    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
525:  }
526:
527:  // Guard 1: did we already charge for this purpose?
528:  try {
529:    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
530:    if (existing?.status === "succeeded") {
531:      return {
532:        ok: true,
533:        paymentIntentId: existing.id,
534:        amountCents: existing.amount_received || existing.amount,
535:        replayed: true,
536:      };
537:    }
538:    if (existing?.status === "requires_action") {
539:      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
540:      // again, so reuse the existing intent (and its link) rather than piling up a
541:      // new challenge every retry. A DIFFERENT card is a different story — if the
542:      // customer has since saved one, cancel the stale challenge and really try it,
543:      // otherwise saving a new card would silently change nothing.
544:      const pendingPm =
545:        typeof existing.payment_method === "string"
546:          ? existing.payment_method
547:          : (existing.payment_method?.id ?? null);
548:      if (pendingPm === user.stripePaymentMethodId) {
549:        return {
550:          ok: false,
551:          kind: "requires_action",
552:          paymentIntentId: existing.id,
553:          message: "Awaiting bank confirmation",
554:        };
555:      }
556:      await cancelIfUnconfirmed(existing.id);
557:    }
558:    if (existing?.status === "processing") {
559:      return { ok: false, kind: "transient", message: "A charge for this period is still settling" };
560:    }
561:  } catch (e) {
562:    // A failed lookup must not become a blind second charge.
563:    console.error("[cards] pre-flight charge lookup failed", e);
564:    return { ok: false, kind: "transient", message: "Could not verify existing charges" };
565:  }
566:
567:  try {
568:    const pi = await stripe().paymentIntents.create(
569:      {
570:        amount: amountCents,
571:        currency: "usd",
572:        customer: user.stripeCustomerId,
573:        payment_method: user.stripePaymentMethodId,
574:        confirm: true,
575:        off_session: true,
576:        // No browser exists here, so a redirect-based next_action could never be
577:        // satisfied — and asking for one is what makes Stripe demand a return_url.
578:        automatic_payment_methods: { enabled: true, allow_redirects: "never" },
579:        description,
580:        metadata: { ...(opts.metadata ?? {}), nxeonUserId: user.id, nxeonChargeKey: marker },
581:      },
582:      { idempotencyKey },
583:    );
584:    if (pi.status === "succeeded") {
585:      return { ok: true, paymentIntentId: pi.id, amountCents: pi.amount_received || pi.amount, replayed: false };
586:    }
587:    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
588:      return { ok: false, kind: "requires_action", paymentIntentId: pi.id, message: "Bank confirmation required" };
589:    }
590:    if (pi.status === "processing") {
591:      return { ok: false, kind: "transient", message: "Payment is still processing" };
592:    }
593:    return { ok: false, kind: "declined", message: `Payment could not be completed (${pi.status})` };
594:  } catch (e) {
595:    return classifyChargeError(e);
596:  }
597:}
