119	/** Lower bound for "have we already sent this notification recently?" lookups. */
120	export function dedupeSince(now: Date, days: number = NOTIFY_DEDUPE_DAYS): Date {
121	  return new Date(now.getTime() - days * DAY_MS);
122	}
