145	/**
146	 * What the sweep should do with an item that is past its expiry date.
147	 *  - `renew`   charge the wallet and push `expiresAt` forward
148	 *  - `grace`   still inside the grace window: leave it running, nag the owner
149	 *  - `enforce` grace elapsed and unpaid: suspend (email) / detach (volume)
150	 */
151	export type RenewalAction = "renew" | "grace" | "enforce";
152	
153	export function renewalDecision(opts: {
154	  expiresAt: Date;
155	  now: Date;
156	  autoRenew: boolean;
157	  balanceCents: number;
158	  priceCents: number;
159	  graceDays?: number;
160	}): RenewalAction {
161	  const { expiresAt, now, autoRenew, balanceCents, priceCents } = opts;
162	  if (autoRenew && canAfford(balanceCents, priceCents)) return "renew";
163	  if (isPastGrace(expiresAt, now, opts.graceDays)) return "enforce";
164	  return "grace";
165	}
