169	 * renewal would actually fail today (auto-renew off, or wallet too low).
170	 */
171	export function needsUpcomingWarning(opts: {
172	  autoRenew: boolean;
173	  balanceCents: number;
174	  priceCents: number;
175	}): boolean {
176	  return !(opts.autoRenew && canAfford(opts.balanceCents, opts.priceCents));
177	}

