 99	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
100	  const session = await stripe().checkout.sessions.retrieve(sessionId);
101	  const userId = session.metadata?.nxeonUserId;
102	  const cents = session.amount_total ?? 0;
103	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
104	
105	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
106	  // session id inside the description.
107	  const legacy = await db.walletTransaction.findFirst({
108	    where: { stripeSessionId: null, description: { contains: session.id } },
109	  });
110	  if (legacy) return false;
111	
112	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
113	  // read-then-write check. The confirm-redirect and the webhook can arrive
114	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
115	  // only the database can safely decide the winner. P2002 == already credited.
116	  try {
117	    await db.$transaction([
118	      db.walletTransaction.create({
119	        data: {
120	          userId,
121	          amountCents: cents,
122	          description: `Stripe payment (${session.id})`,
123	          stripeSessionId: session.id,
124	        },
125	      }),
126	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
127	      db.notification.create({
128	        data: {
129	          userId,
130	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
131	          href: "/dashboard/billing",
132	        },
133	      }),
134	      // PAID invoice for the top-up. Created in the SAME guarded transaction as
135	      // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
136	      // the credit idempotent also prevents a duplicate invoice on replay.
137	      db.invoice.create({
138	        data: invoiceCreateData({
139	          userId,
140	          description: "Wallet top-up",
141	          status: "PAID",
142	          lineItems: [
143	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
144	          ],
145	        }),
146	      }),
147	    ]);
148	  } catch (e) {
149	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
150	    throw e;
151	  }
152	  // A funded wallet is the referred user's first paid action — reward both sides.
153	  try {
154	    const { maybeRewardReferral } = await import("./actions-growth");
155	    await maybeRewardReferral(userId);
156	  } catch { /* best-effort */ }
157	  try {
158	    const u = await db.user.findUnique({ where: { id: userId } });
159	    if (u) {
160	      const { sendMail, emails } = await import("./mailer");
161	      const tpl = emails.receipt(`$${(cents / 100).toFixed(2)}`, "wallet top-up");
162	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html });
163	    }
164	  } catch { /* best-effort */ }
165	  return true;
166	}

